const useQueueItemClient = ({
  item,
  onSteer,
  onRemove,
}: {
  item: QueueItemState;
  onSteer: () => void;
  onRemove: () => void;
}): ClientOutput<"queueItem"> => {
  return {
    getState: () => item,
    steer: onSteer,
    remove: onRemove,
  };
};

const QueueItemClient = resource(useQueueItemClient);

// Composer Client - minimal implementation
const useComposerClientResource = ({
  type,
  isEditing,
