36	function syncRepositoryIncrementally(
37	  runtime: ExternalStoreThreadRuntimeCore,
38	  messageRepository: NonNullable<ExternalStoreAdapter['messageRepository']>
39	): readonly ThreadMessage[] {
40	  const repository = (runtime as unknown as { repository: ExternalStoreThreadRuntimeCore['repository'] }).repository
41	  const incomingIds = new Set(messageRepository.messages.map(({ message }) => message.id))
42	
43	  for (const { message, parentId } of messageRepository.messages) {
44	    repository.addOrUpdateMessage(parentId, message)
45	  }
46	
47	  for (const { message } of repository.export().messages) {
48	    if (!incomingIds.has(message.id)) {
49	      repository.deleteMessage(message.id)
50	    }
51	  }
52	
53	  const headId = messageRepository.headId ?? messageRepository.messages.at(-1)?.message.id ?? null
54	
55	  repository.resetHead(headId)
56	
57	  return repository.getMessages()
58	}
